/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import { loadFont, loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Interactive,
  type InteractivitySchema,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * Hello Zoom — words flicker on a dark card and grow, one word lands huge on a
 * light card, the rest of its line types on, then the camera flies through a
 * letter. The type is a hole, not ink: the next card has been behind it all along.
 *
 * Every number is measured frame by frame off the reference. The scene is drawn
 * in a 1920-wide stage and scaled to the composition, so the numbers read as
 * reference px at any size.
 */

const { fontFamily: INTER } = loadFont("normal", {
  weights: ["500", "600", "700", "800"],
  subsets: ["latin"],
});

const STAGE_W = 1920;

/** Piecewise-linear lookup over [frame, value] pairs, held at the ends. */
const track = (pts: readonly (readonly [number, number])[], t: number) => {
  if (t <= pts[0]![0]) return pts[0]![1];
  for (let i = 1; i < pts.length; i++) {
    const [t1, v1] = pts[i]!;
    const [t0, v0] = pts[i - 1]!;
    if (t <= t1) return v0 + ((v1 - v0) * (t - t0)) / (t1 - t0);
  }
  return pts[pts.length - 1]![1];
};

// --- The shot list, in frames at 30fps ---------------------------------------

/** The words share this many beats; the cut to the lead takes the last one. */
const FLICKER_BEATS = 21;
const LEAD_AT = 20;
const LINE_AT = 25;
const TYPE_FRAMES = 5;
const NEXT_AT = 49;

/** Font size and baseline below centre of each word, read across the flicker. */
const WORD_SIZE = [75.4, 93.7, 115.9, 124.9, 150.2, 186.3, 225.1];
const WORD_DROP = [20.4, 25.3, 30.2, 31.9, 40.5, 49.9, 60.1];
/** Each word sits this far off true centre in the reference, px. */
const WORD_NUDGE = [-0.3, -1.8, -2, -0.8, -0.3, -2.1, -2.9];
const WORD_TRACKING = -0.02;

const LEAD_SIZE = 433.14;
const LEAD_DROP = 156.57;
const LEAD_TRACKING = -0.047;
/** The reference sets the lead this far left of true centre, px. */
const LEAD_NUDGE = -17.7;
/** The lead starts to leave before the cut: px left of centre. */
const LEAD_DRIFT = [
  [20, 0],
  [21, 1.54],
  [22, 4.37],
  [23, 9.37],
  [24, 18],
] as const;

const LINE_SIZE = 210.38;
const LINE_TRACKING = -0.025;
/** How much of the way from its resting spot to a centred lead the line starts. */
const LINE_START = 0.6893;
/** The line's slide to rest, as the fraction of that distance still to go. */
const LINE_SLIDE = [
  [25, 1],
  [26, 0.6139],
  [27, 0.3242],
  [28, 0.183],
  [29, 0.1012],
  [30, 0.0503],
  [31, 0.0203],
  [32, 0.0047],
  [33, 0],
] as const;

/** The push through the letter, about the middle of the stage. */
const ZOOM = [
  [36, 1],
  [37, 1.0036],
  [38, 1.0155],
  [39, 1.0371],
  [40, 1.071],
  [41, 1.1213],
  [42, 1.1947],
  [43, 1.3018],
  [44, 1.4694],
  [45, 1.7476],
  [46, 2.2753],
  [47, 3.5662],
  [48, 11.7],
] as const;

/** The camera drifts off the stage's centre as it dives, px. */
const ZOOM_X = [
  [37, 0],
  [38, -0.3],
  [44, -0.64],
  [45, -0.98],
  [46, -2.27],
  [47, -1.25],
  [48, -30.9],
] as const;
const ZOOM_Y = [
  [42, 0],
  [43, 0.15],
  [45, 0.18],
  [46, 0.74],
  [47, 2.13],
  [48, 4.35],
] as const;

const NEXT_SIZE = 74;
const NEXT_DROP = 19.7;
/** The next word rushes up from nothing behind the type, then barely creeps. */
const NEXT_SCALE = [
  [41, 0],
  [42, 0.01],
  [43, 0.0576],
  [44, 0.1023],
  [45, 0.1647],
  [46, 0.262],
  [47, 0.4035],
  [48, 0.615],
  [49, 0.868],
  [50, 0.993],
  [51, 1],
  [75, 1.05],
] as const;

/** Copy never runs wider than this. */
const MAX_WIDTH = 1728;

// --- Timeline helpers --------------------------------------------------------

/** Which word of `count` is up at frame `f`. */
const wordAt = (f: number, count: number) =>
  Math.min(count - 1, Math.floor((f * count) / FLICKER_BEATS));

/** How many characters of `length` have been typed at frame `f`. */
const typedAt = (f: number, length: number) =>
  Math.round(
    Math.min(1, Math.max(0, Math.floor(f - LINE_AT) / TYPE_FRAMES)) * length,
  );

/**
 * The deepest point of ink between columns `from` and `to` of a raster, by
 * chamfer distance to the nearest paper. This is what the camera flies through:
 * aim at a letter's counter and it comes out the far side onto blank paper.
 * Ties go to the point nearest the middle of the span and of `midY`.
 */
const deepestInk = (
  alpha: ArrayLike<number>,
  w: number,
  h: number,
  from: number,
  to: number,
  midY: number,
) => {
  const d = new Float32Array(w * h);
  const at = (x: number, y: number) =>
    x < 0 || y < 0 || x >= w || y >= h ? 0 : d[y * w + x]!;
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++)
      if (alpha[y * w + x]! > 127)
        d[y * w + x] =
          1 +
          Math.min(
            at(x - 1, y),
            at(x, y - 1),
            at(x - 1, y - 1),
            at(x + 1, y - 1),
          );
  for (let y = h - 1; y >= 0; y--)
    for (let x = w - 1; x >= 0; x--)
      if (d[y * w + x]! > 0)
        d[y * w + x] = Math.min(
          d[y * w + x]!,
          1 +
            Math.min(
              at(x + 1, y),
              at(x, y + 1),
              at(x + 1, y + 1),
              at(x - 1, y + 1),
            ),
        );
  const midX = (from + to) / 2;
  let best = { x: midX, y: midY, r: 0 };
  let top = -Infinity;
  for (let y = 0; y < h; y++)
    for (let x = from; x < to; x++) {
      const r = at(x, y);
      const score = r - 0.01 * (Math.abs(x - midX) + Math.abs(y - midY));
      if (r > 0 && score > top) {
        top = score;
        best = { x, y, r };
      }
    }
  return best;
};

interface Metrics {
  /** Advance widths in em. */
  words: number[];
  lead: number;
  /** The lead at the line's tracking. */
  leadInLine: number;
  line: number;
  next: number;
  /** The point of the line the camera flies through: em right of its start, up from its baseline. */
  through: [number, number];
}

/** A canvas shapes type the way the page does, and rasters it for `deepestInk`. */
const measure = (
  face: string,
  weight: number,
  words: string[],
  lead: string,
  line: string,
  next: string,
): Metrics => {
  const P = 100; // raster px per em
  const ctx = document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true })!;
  const setFont = (tracking: number) => {
    ctx.font = `${weight} ${P}px ${face}`;
    ctx.letterSpacing = `${tracking * P}px`;
  };
  const em = (text: string, tracking: number) => {
    setFont(tracking);
    return ctx.measureText(text).width / P;
  };
  const out = {
    words: words.map((w) => em(w, WORD_TRACKING)),
    lead: em(lead, LEAD_TRACKING),
    leadInLine: em(lead, LINE_TRACKING),
    line: em(line, LINE_TRACKING),
    next: em(next, WORD_TRACKING),
  };
  const w = Math.ceil(out.line * P);
  const h = 2 * P;
  const base = 1.3 * P;
  ctx.canvas.width = w;
  ctx.canvas.height = h;
  setFont(LINE_TRACKING); // resizing a canvas resets its state
  ctx.fillText(line, 0, base);
  const { data } = ctx.getImageData(0, 0, w, h);
  const alpha = new Uint8ClampedArray(w * h);
  for (let i = 0; i < alpha.length; i++) alpha[i] = data[i * 4 + 3]!;
  // The middle of the line only: the point lands on the stage's centre, and one
  // near an end would throw the whole line off to the side.
  const p = deepestInk(
    alpha,
    w,
    h,
    Math.round(w * 0.35),
    Math.round(w * 0.65),
    base - 0.26 * P,
  );
  return { ...out, through: [p.x / P, (base - p.y) / P] };
};

/**
 * Chrome snaps a glyph's baseline to a whole device pixel, so a line moving
 * vertically climbs in steps and a resting one sits up to half a pixel off. Two
 * copies a pixel apart, summed in a group, land the baseline anywhere between.
 */
const Line = ({
  x,
  y,
  scale = 1,
  size,
  tracking,
  px,
  fill,
  anchor,
  children,
}: {
  x: number;
  y: number;
  scale?: number;
  size: number;
  tracking: number;
  px: number;
  fill: string;
  anchor?: "middle";
  children: ReactNode;
}) => {
  const row = Math.floor(y * px);
  const f = y * px - row;
  const copy = (base: number, opacity: number) => (
    <text
      transform={`translate(${x} ${base / px}) scale(${scale})`}
      fontSize={size}
      fill={fill}
      opacity={opacity}
      textAnchor={anchor}
      style={{ mixBlendMode: "plus-lighter", letterSpacing: `${tracking}em` }}
    >
      {children}
    </text>
  );
  return (
    <g style={{ isolation: "isolate" }}>
      {copy(row, 1 - f)}
      {copy(row + 1, f)}
    </g>
  );
};

export interface HelloZoomProps {
  /** The words that flicker on the first card. A comma-separated string works too. */
  words?: string[] | string;
  /** The word that lands huge on the second card. */
  lead?: string;
  /** Typed on after the lead. */
  rest?: string;
  /** What the camera finds behind the type. */
  nextWord?: string;
  /** A label from `fonts.ts` or a CSS family you have loaded. Defaults to Inter. */
  fontFamily?: string;
  fontWeight?: number;
  /** The first and last cards, and the type on the second. Defaults to `foreground`. */
  inkColor?: string;
  /** The second card, and the type on the first and last. Defaults to `background`. */
  paperColor?: string;
  /**
   * The point of the resting line the camera flies through, in em right of the
   * line's start and up from its baseline. Unset, it finds the deepest ink near the middle.
   */
  through?: [number, number];
  speed?: number;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const HelloZoomScene = ({
  words = "React, Remotion, shadcn, Next.js, Vite, Tailwind, TypeScript",
  lead = "Hello",
  rest = "Acme.",
  nextWord = "npx",
  fontFamily,
  fontWeight = 700,
  inkColor,
  paperColor,
  through,
  speed = 1,
  theme,
  mode,
}: HelloZoomProps) => {
  const t = useKitTheme(theme, mode);
  const f = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const id = useId().replace(/:/g, "");
  const ink = inkColor ?? t.foreground;
  const paper = paperColor ?? t.background;
  const face = resolveFont(fontFamily) ?? resolveFont(t.fontFamily) ?? INTER;
  const list = (typeof words === "string" ? words.split(",") : words)
    .map((w) => w.trim())
    .filter(Boolean);
  const line = `${lead} ${rest}`;
  const joined = list.join("\n");

  const [m, setM] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("hello-zoom: measuring type"));
  useEffect(() => {
    let live = true;
    // measuring a fallback face measures the wrong face
    document.fonts
      .load(`${fontWeight} 100px ${face}`, joined + line + nextWord)
      .catch(() => undefined)
      .then(() => {
        if (live)
          setM(
            measure(face, fontWeight, joined.split("\n"), lead, line, nextWord),
          );
      });
    return () => {
      live = false;
    };
  }, [face, fontWeight, joined, lead, line, nextWord]);
  useEffect(() => {
    if (m) continueRender(handle);
  }, [m, handle]);

  const W = STAGE_W;
  const H = (STAGE_W * height) / width;
  const cx = W / 2;
  const cy = H / 2;
  const px = width / W;

  const type: CSSProperties = {
    fontFamily: face,
    fontWeight,
    textRendering: "geometricPrecision",
    whiteSpace: "pre",
  };
  const fit = (size: number, em: number) => Math.min(size, MAX_WIDTH / em);

  const scene = () => {
    if (!m) return null;

    const nextScale = track(NEXT_SCALE, f);
    const next = (
      <Line
        x={cx}
        y={cy + NEXT_DROP * nextScale}
        scale={nextScale}
        size={fit(NEXT_SIZE, m.next)}
        tracking={WORD_TRACKING}
        px={px}
        fill={paper}
        anchor="middle"
      >
        {nextWord}
      </Line>
    );

    // ---- 1. the flicker
    if (f < LEAD_AT) {
      const i = wordAt(f, list.length);
      const at = list.length > 1 ? (i / (list.length - 1)) * 6 : 0;
      const row = WORD_SIZE.map((v, j) => [j, v] as const);
      const drop = WORD_DROP.map((v, j) => [j, v] as const);
      const nudge = WORD_NUDGE.map((v, j) => [j, v] as const);
      return (
        <Line
          x={cx + track(nudge, at)}
          y={cy + track(drop, at)}
          size={fit(track(row, at), m.words[i]!)}
          tracking={WORD_TRACKING}
          px={px}
          fill={paper}
          anchor="middle"
        >
          {list[i]}
        </Line>
      );
    }

    // ---- 3. through the letter
    if (f >= NEXT_AT) return next;

    // ---- 2. the light card, its type a window onto the next one
    let lineType: ReactNode;
    if (f < LINE_AT) {
      const size = fit(LEAD_SIZE, m.lead);
      lineType = (
        <Line
          x={cx - (m.lead * size) / 2 + LEAD_NUDGE - track(LEAD_DRIFT, f)}
          y={cy + LEAD_DROP}
          size={size}
          tracking={LEAD_TRACKING}
          px={px}
          fill="#fff"
        >
          {lead}
        </Line>
      );
    } else {
      const [tx, ty] = through ?? m.through;
      const reach = Math.max(tx, m.line - tx);
      const size = Math.min(LINE_SIZE, MAX_WIDTH / 2 / reach);
      const rest0 = cx - tx * size;
      const start = cx - (m.leadInLine * size) / 2;
      const x = rest0 + track(LINE_SLIDE, f) * LINE_START * (start - rest0);
      const y = cy + ty * size;
      const s = track(ZOOM, f);
      const n = typedAt(f, rest.length);
      lineType = (
        <Line
          x={cx + s * (x - cx) + track(ZOOM_X, f)}
          y={cy + s * (y - cy) + track(ZOOM_Y, f)}
          scale={s}
          size={size}
          tracking={LINE_TRACKING}
          px={px}
          fill="#fff"
        >
          {n > 0 ? `${lead} ${rest.slice(0, n)}` : lead}
        </Line>
      );
    }
    return (
      <>
        <mask
          id={id}
          maskUnits="userSpaceOnUse"
          x={0}
          y={0}
          width={W}
          height={H}
        >
          {lineType}
        </mask>
        <g mask={`url(#${id})`}>
          <rect width={W} height={H} fill={ink} />
          {next}
        </g>
      </>
    );
  };

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ background: f >= LEAD_AT && f < NEXT_AT ? paper : ink }}
    >
      <svg
        viewBox={`0 0 ${W} ${H}`}
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0, ...type }}
      >
        {scene()}
      </svg>
    </AbsoluteFill>
  );
};

